# Builds battles/gettysburg/battle.json. Run from the repo root: python3 battles/gettysburg/make.py
# Local metres from 39.8130N 77.2350W (x east, y north). The 10 km square holds Herr Ridge and the Chambersburg Pike to
# Marsh Creek in the west, Oak Hill, Barlow's Knoll and the town in the north, Culp's Hill, Benner's Hill and Wolf Hill in
# the east, Cemetery Ridge, the Peach Orchard, the Wheatfield, Devil's Den and both Round Tops in the middle and south,
# and Merritt's field on the Emmitsburg Road in the south-west corner. East Cavalry Field, Cashtown, Hunterstown and
# Two Taverns are outside it. Every place is kept in latitude and longitude below and converted once. Farms, buildings,
# hills and the War Department's division and brigade tablets are OpenStreetMap points and the tablets' own coordinates,
# as the research note gives them; the roads and streams are OpenStreetMap ways on their 1863 lines, the woods the
# park's OpenStreetMap polygons, which the park has cut back to the 1863 outlines. Long Lane, Brinkerhoff's Ridge, the
# Bliss farm and the bivouacs the tablets describe in words are placed within 150 to 400 m and labelled "about here".
# A modern quarry on the Baltimore Pike and Lake Heritage, a 1970s reservoir, are filled.
import json, math, re, datetime as dt
HERE = "battles/gettysburg/"
LAT0, LON0 = 39.8130, -77.2350
KX, KY = 111320 * math.cos(math.radians(LAT0)), 111320  # tools/fetch_terrain.py's metres per degree
def M(lat, lon): return (round((lon - LON0) * KX), round((lat - LAT0) * KY))
EDGE = 5000

# ---- terrain: fill the quarry and the reservoir with a smooth (harmonic) surface from their rims ----
T = json.load(open(HERE + "terrain.json"))
COLS, SP = T["cols"], T["spacing"]; HALF = COLS * SP / 2
def cell(x, y): return int((HALF - y) / SP), int((x + HALF) / SP)
def centre(r, c): return (-HALF + (c + 0.5) * SP, HALF - (r + 0.5) * SP)
QUARRY = (1600, -1150, 2070, -760)  # x0, y0, x1, y1: the pit falls to 68 m beside Rock Creek, which runs at 130 m
LAKE = (3300, -1300, 4700, 450)     # Lake Heritage's flat surface at 144.9 m lies along this valley
def fill(mask):
    Z = T["z"]; v = {rc: Z[rc[0] * COLS + rc[1]] for rc in mask}
    get = lambda r, c: v.get((r, c), Z[r * COLS + c])
    for _ in range(4000):  # over-relaxed Gauss-Seidel; the result depends only on the rim, so a second run changes nothing
        worst = 0
        for (r, c), old in v.items():
            new = old + 1.9 * ((get(r - 1, c) + get(r + 1, c) + get(r, c - 1) + get(r, c + 1)) / 4 - old); v[(r, c)] = new; worst = max(worst, abs(new - old))
        if worst < 1e-4: break
    for (r, c), val in v.items(): Z[r * COLS + c] = round(val, 1)
def box(x0, y0, x1, y1):
    (r1, c0), (r0, c1) = cell(x0, y0), cell(x1, y1)
    return {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)}
before = list(T["z"])
fill(box(*QUARRY))
flat = {rc for rc in box(*LAKE) if 144.6 < T["z"][rc[0] * COLS + rc[1]] < 145.3}
fill({(r + dr, c + dc) for r, c in flat for dr in (-1, 0, 1) for dc in (-1, 0, 1)})  # the shore cells too
assert min(T["z"]) > 0.1, min(T["z"])  # the page draws exactly 0 as missing data
assert min(T["z"][r * COLS + c] for r, c in box(*QUARRY)) > 115, "the quarry is filled"
if T["z"] != before: json.dump(T, open(HERE + "terrain.json", "w"), separators=(",", ":"))
def z(x, y):
    r, c = cell(x, y)
    return T["z"][r * COLS + c] if 0 <= c < COLS and 0 <= r < COLS else 999
def on_map(p, m=0): return max(abs(p[0]), abs(p[1])) <= EDGE - m

