# The woods are the park's OpenStreetMap polygons. The Wheatfield (about 19 acres) and Sherfy's Peach Orchard are the
# note's boxes, drawn from the tablets round them; everything not wooded is farmland, cut into parcels about 600 m across.
WOOD_BOX = [(min(x for x, _ in w), min(y for _, y in w), max(x for x, _ in w), max(y for _, y in w)) for w in WOODS]
def wooded(x, y): return any(b[0] <= x <= b[2] and b[1] <= y <= b[3] and inside(x, y, w) for w, b in zip(WOODS, WOOD_BOX))
def quad(x0, y0, x1, y1): return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
WHEATFIELD = quad(-780, -1850, -500, -1600)
